bool checkInclusion(char* s1, char* s2) {
    int n = strlen(s1), m = strlen(s2);
    if (n > m) return false;
    int need[26] = {0}, window[26] = {0};
    for (int i = 0; i < n; i++) need[s1[i] - 'a']++;
    for (int i = 0; i < m; i++) {
        window[s2[i] - 'a']++;
        if (i >= n) window[s2[i - n] - 'a']--;
        if (i >= n - 1) {
            bool match = true;
            for (int j = 0; j < 26; j++) {
                if (need[j] != window[j]) { match = false; break; }
            }
            if (match) return true;
        }
    }
    return false;
}

